#if defined(DEFERRED_EXEC_ENABLE)
#    if defined(DYNAMIC_MACRO_ENABLE)
deferred_token dynamic_macro_token = INVALID_DEFERRED_TOKEN;

static uint32_t dynamic_macro_led(uint32_t trigger_time, void *cb_arg) {
    static bool led_state = true;
    if (!is_launching) {
        led_state = !led_state;
        ML_LED_3(led_state);
    }
    return 100;
}

bool dynamic_macro_record_start_kb(int8_t direction) {
    if (!dynamic_macro_record_start_user(direction)) {
        return false;
    }
    if (dynamic_macro_token == INVALID_DEFERRED_TOKEN) {
        ML_LED_3(true);
        dynamic_macro_token = defer_exec(100, dynamic_macro_led, NULL);
    }
    return true;
}

bool dynamic_macro_record_end_kb(int8_t direction) {
    if (!dynamic_macro_record_end_user(direction)) {
        return false;
    }
    if (cancel_deferred_exec(dynamic_macro_token)) {
        dynamic_macro_token = INVALID_DEFERRED_TOKEN;
        ML_LED_3(false);
    }
    return false;
}
#    endif

static uint32_t startup_exec(uint32_t trigger_time, void *cb_arg) {
    static uint8_t startup_loop = 0;

    switch (startup_loop++) {
        case 0:
            ML_LED_1(true);
            ML_LED_2(false);
            ML_LED_3(false);
            ML_LED_4(false);
            ML_LED_5(false);
            ML_LED_6(false);
            break;
        case 1:
            ML_LED_2(true);
            break;
        case 2:
            ML_LED_3(true);
            break;
        case 3:
            ML_LED_4(true);
            break;
        case 4:
            ML_LED_5(true);
            break;
        case 5:
            ML_LED_6(true);
            break;
        case 6:
            ML_LED_1(false);
            break;
        case 7:
            ML_LED_2(false);
            break;
        case 8:
            ML_LED_3(false);
            break;
        case 9:
            ML_LED_4(false);
            break;
        case 10:
            ML_LED_5(false);
            break;
        case 11:
            ML_LED_6(false);
            break;
        case 12:
            is_launching = false;
            layer_state_set_kb(layer_state);
            return 0;
    }
    return 250;
}
